<?php
namespace App\Http\Controllers; use App\Models\Supplier; use Illuminate\Http\Request; use Inertia\Inertia; use Illuminate\Support\Facades\Http; class SupplierController extends Controller {public function lookupCui(Request $r){$cui=preg_replace('/\\D+/','',(string)$r->input('cui')); abort_if(strlen($cui)<2,422,'CUI invalid.'); $res=Http::timeout(12)->acceptJson()->post('https://webservicesp.anaf.ro/api/PlatitorTvaRest/v9/tva',[['cui'=>(int)$cui,'data'=>now()->format('Y-m-d')]]); if(!$res->successful()||empty($res->json('found.0'))){return response()->json(['message'=>'CUI negăsit sau serviciul ANAF indisponibil.'],404);} $f=$res->json('found.0'); $g=$f['date_generale']??$f; $tax=$f['inregistrare_scop_Tva']??$f['scpTVA']??false; return response()->json(['name'=>$g['denumire']??$g['name']??'','cui'=>$cui,'address'=>$g['adresa']??'','phone'=>$g['telefon']??'','postal_code'=>$g['codPostal']??'','registration_number'=>$g['nrRegCom']??'','vat_status'=>$tax?'Plătitor TVA':'Neplătitor TVA','raw'=>$f]);} public function index(){return Inertia::render('Suppliers/Index',['suppliers'=>Supplier::withCount(['documents','receptions'])->latest()->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:180','cui'=>'nullable|string|max:30','registration_number'=>'nullable|string|max:60','address'=>'nullable|string|max:255','email'=>'nullable|email','phone'=>'nullable|string|max:40','iban'=>'nullable|string|max:40','bank'=>'nullable|string|max:120']);Supplier::create($d);return back()->with('success','Furnizor creat.');} public function update(Request $r,Supplier $supplier){$supplier->update($r->validate(['name'=>'required|string|max:180','cui'=>'nullable|string|max:30','registration_number'=>'nullable|string|max:60','address'=>'nullable|string|max:255','email'=>'nullable|email','phone'=>'nullable|string|max:40','iban'=>'nullable|string|max:40','bank'=>'nullable|string|max:120','active'=>'boolean']));return back();} }
